def dong_may(item_name):
    item_name = str(item_name).strip()
    # iPhone là hãng Apple, dòng máy là iPhone
    if 'iPhone' in item_name:
        return 'iPhone'
    # Loại bỏ phần dung lượng GB
    parts = item_name.split()
    result = []
    for part in parts:
        if part.endswith('GB') or part.endswith('gb'):
            continue
        result.append(part)
    return ' '.join(result).strip()

