def xe_toi_nhieu_lan(p, k=None):
    o = orders(p)
    o = o[(o["valid"] == True) & (o["revenue"] > 0) & (o["warranty"] == False)]
    plate_count = o.groupby("plate").size()
    plate_count = plate_count[plate_count >= 2]
    plate_count = plate_count.sort_values(ascending=False)
    if k is not None:
        return list(plate_count.head(k).index)
    return list(plate_count.index)

